#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <string>

constexpr std::uint64_t encode(const char* s) {
    std::uint64_t value = 0;
    while (*s) {
        const unsigned code =
            *s == 'A' ? 0u :
            *s == 'C' ? 1u :
            *s == 'G' ? 2u : 3u;
        value = (value << 2) | code;
        ++s;
    }
    return value;
}

constexpr std::uint64_t mask(unsigned k) {
    return (std::uint64_t{1} << (2 * k)) - 1;
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;

    char* end = nullptr;
    const long n = std::strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') return 1;
    (void)n;

    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::array<unsigned char, 256> codes;
    codes.fill(255);
    codes['A'] = codes['a'] = 0;
    codes['C'] = codes['c'] = 1;
    codes['G'] = codes['g'] = 2;
    codes['T'] = codes['t'] = 3;

    std::array<std::uint64_t, 4> singles{};
    std::array<std::uint64_t, 16> pairs{};

    std::uint64_t count3 = 0;
    std::uint64_t count4 = 0;
    std::uint64_t count6 = 0;
    std::uint64_t count12 = 0;
    std::uint64_t count18 = 0;
    std::uint64_t length = 0;

    // Initial T padding cannot match an incomplete fragment: all start with G.
    std::uint64_t rolling = ~std::uint64_t{0};

    constexpr auto target3 = encode("GGT");
    constexpr auto target4 = encode("GGTA");
    constexpr auto target6 = encode("GGTATT");
    constexpr auto target12 = encode("GGTATTTTAATT");
    constexpr auto target18 = encode("GGTATTTTAATTTATAGT");

    bool in_three = false;
    std::string line;
    line.reserve(256);

    while (std::getline(std::cin, line)) {
        if (!line.empty() && line[0] == '>') {
            if (in_three) break;
            if (line.compare(0, 6, ">THREE") == 0 &&
                (line.size() == 6 || line[6] == ' ' ||
                 line[6] == '\t' || line[6] == '\r')) {
                in_three = true;
            }
            continue;
        }

        if (!in_three || line.empty() || line[0] == ';') continue;

        for (unsigned char ch : line) {
            const unsigned code = codes[ch];
            if (code == 255) continue;

            rolling = (rolling << 2) | code;
            ++singles[code];
            if (++length > 1) ++pairs[rolling & 15];

            count3 += ((rolling & mask(3)) == target3);
            count4 += ((rolling & mask(4)) == target4);
            count6 += ((rolling & mask(6)) == target6);
            count12 += ((rolling & mask(12)) == target12);
            count18 += ((rolling & mask(18)) == target18);
        }
    }

    constexpr char alphabet[] = "ACGT";
    std::cout << std::fixed << std::setprecision(3);

    std::array<unsigned, 4> order1{{0, 1, 2, 3}};
    std::sort(order1.begin(), order1.end(), [&](unsigned a, unsigned b) {
        return singles[a] != singles[b]
            ? singles[a] > singles[b] : a < b;
    });

    for (unsigned code : order1) {
        if (singles[code] == 0) continue;
        std::cout << alphabet[code] << ' '
                  << 100.0 * static_cast<double>(singles[code]) /
                     static_cast<double>(length)
                  << '\n';
    }
    std::cout << '\n';

    std::array<unsigned, 16> order2{};
    for (unsigned i = 0; i < order2.size(); ++i) order2[i] = i;
    std::sort(order2.begin(), order2.end(), [&](unsigned a, unsigned b) {
        return pairs[a] != pairs[b] ? pairs[a] > pairs[b] : a < b;
    });

    for (unsigned code : order2) {
        if (pairs[code] == 0) continue;
        std::cout << alphabet[code >> 2] << alphabet[code & 3] << ' '
                  << 100.0 * static_cast<double>(pairs[code]) /
                     static_cast<double>(length - 1)
                  << '\n';
    }
    std::cout << '\n';

    std::cout << count3  << "\tGGT\n"
              << count4  << "\tGGTA\n"
              << count6  << "\tGGTATT\n"
              << count12 << "\tGGTATTTTAATT\n"
              << count18 << "\tGGTATTTTAATTTATAGT\n";

    return 0;
}

